package vn.iotstar.controller; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import vn.iotstar.dto.*; import vn.iotstar.service.*; @Controller @RequiredArgsConstructor public class AuthController{private final AuthService auth;private final OtpService otp;@GetMapping("/login") public String login(){return "auth/login";}@GetMapping("/register")public String reg(Model m){m.addAttribute("registerDTO",new RegisterDTO());return "auth/register";}@PostMapping("/register")public String reg(@Valid @ModelAttribute RegisterDTO d,BindingResult r,RedirectAttributes ra){if(r.hasErrors())return "auth/register";try{auth.register(d);ra.addFlashAttribute("success","OTP đã được gửi đến email.");return "redirect:/verify-otp?email="+d.getEmail();}catch(Exception e){r.reject("register.error",e.getMessage());return "auth/register";}}@GetMapping("/verify-otp")public String verifyPage(@RequestParam(required=false)String email,Model m){VerifyOtpDTO d=new VerifyOtpDTO();d.setEmail(email);m.addAttribute("verifyOtpDTO",d);return "auth/verify-otp";}@PostMapping("/verify-otp")public String verify(@Valid @ModelAttribute VerifyOtpDTO d,BindingResult r,RedirectAttributes ra){if(r.hasErrors())return "auth/verify-otp";if(!auth.verifyRegister(d.getEmail(),d.getOtp())){r.reject("otp.error","OTP không hợp lệ hoặc đã hết hạn.");return "auth/verify-otp";}ra.addFlashAttribute("success","Xác nhận thành công. Hãy đăng nhập.");return "redirect:/login";}@PostMapping("/resend-register-otp")public String resend(@RequestParam String email,RedirectAttributes ra){otp.sendRegisterOtp(email);ra.addFlashAttribute("success","Đã gửi lại OTP.");return "redirect:/verify-otp?email="+email;}@GetMapping("/forgot-password")public String forgot(Model m){m.addAttribute("forgotPasswordDTO",new ForgotPasswordDTO());return "auth/forgot-password";}@PostMapping("/forgot-password")public String forgot(@Valid @ModelAttribute ForgotPasswordDTO d,BindingResult r,RedirectAttributes ra){if(r.hasErrors())return "auth/forgot-password";try{auth.forgotPassword(d.getEmail());ra.addFlashAttribute("email",d.getEmail());ra.addFlashAttribute("success","OTP đã được gửi.");return "redirect:/reset-password";}catch(Exception e){r.reject("forgot.error",e.getMessage());return "auth/forgot-password";}}@GetMapping("/reset-password")public String reset(Model m){m.addAttribute("resetPasswordDTO",new ResetPasswordDTO());return "auth/reset-password";}@PostMapping("/reset-password")public String reset(@Valid @ModelAttribute ResetPasswordDTO d,BindingResult r,@RequestParam String otp,RedirectAttributes ra){if(!d.getPassword().equals(d.getConfirmPassword()))r.reject("password.error","Mật khẩu xác nhận không đúng.");if(r.hasErrors())return "auth/reset-password";if(!auth.verifyResetOtp(d.getEmail(),otp)){r.reject("otp.error","OTP không hợp lệ hoặc đã hết hạn.");return "auth/reset-password";}auth.resetPassword(d.getEmail(),d.getPassword());ra.addFlashAttribute("success","Đổi mật khẩu thành công.");return "redirect:/login";}}